            throw e;
        } catch (Exception e) {
            log.error("주소 수정 중 오류 발생: 사용자={}, 주소ID={}, 오류={}",
                    email, updateDto.getAddressId(), e.getMessage(), e);
            throw new ShipmentException(ShipmentErrorCode.ADDRESS_UPDATE_ERROR, e);
        }
    }


    @Transactional
    public void deleteAddress(String email, Long addressId) {
        try {
            Product user = userRepository.findByEmail(email)
                    .orElseThrow(() -> new ShipmentProductNotFoundException(
                            "이메일 '" + email + "'에 해당하는 사용자를 찾을 수 없습니다."
                    ));

            log.info("주소 삭제 시작: 사용자={}, 주소ID={}", email, addressId);

            Shipment address = addressRepository.findByIdAndUser(addressId, user)
                    .orElseThrow(() -> new ShipmentNotFoundException(
                            "주소 ID '" + addressId + "'에 해당하는 주소를 찾을 수 없습니다."
                    ));

            addressRepository.delete(address);
            log.info("주소 삭제 완료: 사용자={}, 주소ID={}", email, addressId);
        } catch (ShipmentException e) {
            throw e;
        } catch (Exception e) {
            log.error("주소 삭제 중 오류 발생: 사용자={}, 주소ID={}, 오류={}",
                    email, addressId, e.getMessage(), e);
            throw new ShipmentException(ShipmentErrorCode.ADDRESS_DELETE_ERROR, e);
        }
    }
